SELECT '0.12.0-alpha.collective1.mean1.remote1',label,'published',engine_id,
 jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{metadata}','{"id":"vivienda-realism","notes":"Añadida regularización de viviendas consolidadas con oferta formal, aptitud registral y financiación potencial separadas. Acceso y protección: costes por beneficiario, referencias ejecutadas, avales contingentes, parque público y suspensión cancelable. Regularización: máximo conservador 100.000 expedientes; 95 % ya utilizado, solo 5 % de disponibilidad adicional; efectos colectivos reducidos. Fiscalidad: selectores de tipo/recargo, dos componentes ITP/AJD, IRPF/IS, nuevas bases explícitas, recaudación propia y bloqueo transversal del mismo impuesto. Expropiación para alquiler público: justiprecio aproximado, 5 % legal separado, tramitación y rechazo político explícitos. Aplicadas todas las recomendaciones de coherencia: mercado segmentado, stock público, producción privada, beneficiarios, contabilidad financiera, esfuerzo de compra y fiscalidad por hogar. Felicidad social: todos los colectivos salvo no residentes, incidencia fiscal reforzada, PIB real y rebote colectivo finito. Alquiler inicial corregido a la media aritmética AEAT 2024: 9,00 €/m²/mes, territorio fiscal común; mediana SERPAVI sustituida. Sustituida acogida temporal por cupo para nuevas autorizaciones de teletrabajo internacional de rentas altas; controles, costes y canales económicos propios.","title":"Modelo nacional de vivienda","version":"0.12.0-alpha.collective1.mean1.remote1","created_at":"2026-10-04T00:00:00.000Z","updated_at":"2026-10-05T11:58:00.648Z"}'::jsonb),'{model,measures}',(select jsonb_agg(case when item->>'id'='a3_migration_reception' then '{"id":"a3_migration_remote_workers","cons":["Menor consumo local y recaudación potencial de nuevos residentes","Impacto nacional limitado; requiere reforma legal y puede desplazar demanda entre destinos"],"name":"Limitar nuevas autorizaciones de teletrabajo internacional de rentas altas","pros":["Menor competencia de nuevos hogares con ingresos exterio