aries":true},{"id":"effect_9","amount":-0.15,"requires":[],"max_value":null,"min_value":null,"operation":"points","permanent":false,"target_id":"resident_owners","delay_turns":1,"target_type":"group","duration_turns":12,"maturation_turns":2,"on_beneficiaries":true},{"id":"effect_10","amount":0,"requires":[],"max_value":null,"min_value":null,"operation":"percent","permanent":false,"target_id":"gdp","delay_turns":1,"target_type":"variable","duration_turns":12,"maturation_turns":2},{"id":"effect_11","amount":0,"requires":[],"max_value":null,"min_value":null,"operation":"percent","permanent":false,"target_id":"population","delay_turns":1,"target_type":"variable","duration_turns":12,"maturation_turns":2},{"id":"effect_12","amount":0,"requires":[],"max_value":null,"min_value":null,"operation":"percent","permanent":false,"target_id":"rent_demand","delay_turns":1,"target_type":"variable","duration_turns":12,"maturation_turns":2},{"id":"effect_13","amount":0,"requires":[],"max_value":null,"min_value":null,"operation":"percent","permanent":false,"target_id":"buy_demand","delay_turns":1,"target_type":"variable","duration_turns":12,"maturation_turns":2},{"id":"effect_14","amount":0,"requires":[],"max_value":null,"min_value":null,"operation":"percent","permanent":false,"target_id":"tourists","delay_turns":1,"target_type":"variable","duration_turns":12,"maturation_turns":2},{"id":"effect_15","amount":0,"requires":[],"max_value":null,"min_value":null,"operation":"percent","permanent":false,"target_id":"tourist_homes","delay_turns":1,"target_type":"variable","duration_turns":12,"maturation_turns":2}],"enabled":true,"sources":["international_remote_work","international_remote_faq","migration_gdp_bde"],"category":"migration","mechanism":"Limita nuevas autorizaciones del régimen de teletrabajo internacional para solicitantes con ingresos exteriores superiores al umbral. El cupo se aplica solo a este grupo. La reducción de entradas se despliega gradualmente y resta nuevas personas, presión de alquiler y demanda de compra frente al escenario sin medida. No crea viviendas. Las rentas del empleador exterior no se cuentan como producción española; la contrapartida económica es menor actividad doméstica por consumo y menor recaudación potencial. Se descuentan las entradas que ya evita una restricción general de permisos.","permanent":false,"risk_high":false,"audit_note":"Hipótesis del juego, sin estimación causal: 20.000 solicitantes nuevos/año con ingresos exteriores de al menos 60.000 €/año. La distribución por encima del umbral usa una cola potencial de exponente 1,7. No es una cifra oficial ni representa a todos los extranjeros. Limita nuevas autorizaciones específicas de teletrabajo internacional de terceros países; no expulsa residentes, no afecta a empleados de empresas españolas ni a la libre circulación europea. Los salarios pagados por empresas exteriores no se incorporan automáticamente al PIB español: se modela únicamente actividad doméstica ligada a consumo. Mayor renta añade presión de alquiler y, en menor medida, compra. Las autorizaciones restringidas por la medida general de permisos se descuentan para evitar duplicación.","cost_audit":{"quantity":20000,"unit":"nuevas solicitudes de rentas altas/año","initial_unit":100,"quarter_unit":100,"annual_maintenance_per_home":0,"sources":["international_remote_work","international_remote_faq"],"note":"Implantación máxima 2 M€ y gestión máxima 8 M€/año. Costes administrativos hipotéticos proporcionales a la restricción efectiva; no gasto de acogida ni manutención."},"rationales":["Menos nuevos inquilinos de rentas altas puede reducir ingresos y valor de alquiler; valoración hipotética.","Menor demanda y consumo local puede reducir rentabilidad; salarios exteriores no equivalen a productividad española.","Menor competencia de entrada puede mejorar acceso; incluye inquilinos de cualquier nacionalidad.","Menor demanda de compra adicional puede mejorar acceso de residentes.","No se aplica al colectivo de compradores no residentes ni presupone su nacionalidad.","Menor consumo en comercios y menor demanda patrimonial; balance heterogéneo y efecto directo pequeño."],"delay_turns":1,"competencies":["national"],"dependencies":[],"effect_scale":1,"initial_cost":2000000,"legal_status":"design_subject_to_legal_review","intensity_max":1,"intensity_min":0,"cost_breakdown":{"homes_at_full":0,"annual_maintenance_per_home":0},"duration_turns":12,"intensity_step":0.01,"quarterly_cost":2000000,"exclusive_group":null,"migration_flows":{"immigration_per_year":-20000,"emigration_per_year":0,"maturation_turns":2,"note":"Entradas nuevas evitadas respecto al escenario; nunca salidas ni expulsiones."},"regulation_note":"Propuesta hipotética de reforma estatal del régimen de teletrabajo internacional; la ley vigente define el régimen, no establece este cupo ni este umbral de renta alta.","full_application":"Cupo 0–20.000 nuevas autorizaciones/año · umbral 60.000–150.000 €/año · aplicación durante 3 años","unit_cost_status":"explicit_administrative_estimate","effect_scale_note":"Hipótesis del juego, sin estimación causal: 20.000 solicitantes nuevos/año con ingresos exteriores de al menos 60.000 €/año. La distribución por encima del umbral usa una cola potencial de exponente 1,7. No es una cifra oficial ni representa a todos los extranjeros. Limita nuevas autorizaciones específicas de teletrabajo internacional de terceros países; no expulsa residentes, no afecta a empleados de empresas españolas ni a la libre circulación europea. Los salarios pagados por empresas exteriores no se incorporan automáticamente al PIB español: se modela únicamente actividad doméstica ligada a consumo. Mayor renta añade presión de alquiler y, en menor medida, compra. Las autorizaciones restringidas por la medida general de permisos se descuentan para evitar duplicación.","coefficient_status":"game_assumption_not_empirical_estimate","regulation_sources":["constitution","international_remote_work","migration_law"],"intensity_description":"Elige cuántas nuevas autorizaciones permites al año dentro del grupo con ingresos superiores al umbral. Un cupo mayor limita menos; un umbral mayor afecta a menos solicitantes.","national_effects_note":"Hipótesis del juego, sin estimación causal: 20.000 solicitantes nuevos/año con ingresos exteriores de al menos 60.000 €/año. La distribución por encima del umbral usa una cola potencial de exponente 1,7. No es una cifra oficial ni representa a todos los extranjeros. Limita nuevas autorizaciones específicas de teletrabajo internacional de terceros países; no expulsa residentes, no afecta a empleados de empresas españolas ni a la libre circulación europea. Los salarios pagados por empresas exteriores no se incorporan automáticamente al PIB español: se modela únicamente actividad doméstica ligada a consumo. Mayor renta añade presión de alquiler y, en menor medida, compra. Las autorizaciones restringidas por la medida general de permisos se descuentan para evitar duplicación.","allowed_funding_sources":["a3_cut_pensions","a3_cut_health","a3_cut_education","a3_cut_social","a3_cut_employment","a3_cut_unemployment","a3_cut_culture","a3_cut_defence","a3_cut_security","a3_cut_infrastructure","a3_cut_research","a3_cut_transport","a3_tax_irpf","a3_tax_iva","a3_tax_corporate","a3_tax_excise","a3_tax_itp","a3_tax_ajd"],"default_intensity":0.5,"selection_description":"Fija un cupo anual para nuevos residentes de ingresos altos que teletrabajan para empresas del exterior. El umbral de ingresos delimita a quién se aplica: elevarlo reduce el grupo afectado. Un cupo más bajo evita parte de esa demanda de alquiler y compra, pero reduce consumo local y recaudación potencial. Mantiene las autorizaciones existentes y no genera expulsiones.","explanation":"Limita nuevas autorizaciones del régimen de teletrabajo internacional para solicitantes con ingresos exteriores superiores al umbral. El cupo se aplica solo a este grupo. La reducción de entradas se despliega gradualmente y resta nuevas personas, presión de alquiler y demanda de compra frente al escenario sin medida. No crea viviendas. Las rentas del empleador exterior no se cuentan como producción española; la contrapartida económica es menor actividad doméstica por consumo y menor recaudación potencial. Se descuentan las entradas que ya evita una restricción general de permisos. Hipótesis del juego, sin estimación causal: 20.000 solicitantes nuevos/año con ingresos exteriores de al menos 60.000 €/año. La distribución por encima del umbral usa una cola potencial de exponente 1,7. No es una cifra oficial ni representa a todos los extranjeros. Limita nuevas autorizaciones específicas de teletrabajo internacional de terceros países; no expulsa residentes, no afecta a empleados de empresas españolas ni a la libre circulación europea. Los salarios pagados por empresas exteriores no se incorporan automáticamente al PIB español: se modela únicamente actividad doméstica ligada a consumo. Mayor renta añade presión de alquiler y, en menor medida, compra. Las autorizaciones restringidas por la medida general de permisos se descuentan para evitar duplicación.","migration_program":{"kind":"remote_workers","annual_capacity":20000,"unit_cost":400,"eligible_pool":400000,"pool_key":"remote_workers","gdp_per_resident":0.35,"rental_extra_multiplier":2.5,"beneficiary_reference":60000,"note":"Hipótesis del juego, sin estimación causal: 20.000 solicitantes nuevos/año con ingresos exteriores de al menos 60.000 €/año. La distribución por encima del umbral usa una cola potencial de exponente 1,7. No es una cifra oficial ni representa a todos los extranjeros. Limita nuevas autorizaciones específicas de teletrabajo internacional de terceros países; no expulsa residentes, no afecta a empleados de empresas españolas ni a la libre circulación europea. Los salarios pagados por empresas exteriores no se incorporan automáticamente al PIB español: se modela únicamente actividad doméstica ligada a consumo. Mayor renta añade presión de alquiler y, en menor medida, compra. Las autorizaciones restringidas por la medida general de permisos se descuentan para evitar duplicación.","remote_workers":{"annual_applicants":20000,"permit_step":200,"reference_income":60000,"income_min":60000,"income_max":150000,"income_step":5000,"income_tail":1.7,"buy_extra_multiplier":0.6,"broad_permit_reference":100000,"annual_tax_per_worker":9000}},"competency_roles":{"national":{"text":"Reforma y gestiona las nuevas autorizaciones específicas de teletrabajo internacional. Mantiene derechos adquiridos y libre circulación europea; no es una prohibición municipal de residencia.","sources":["constitution","international_remote_work","migration_law"]}},"help_summary":"Un cupo para nuevas autorizaciones de teletrabajo internacional de rentas altas: menor presión de demanda, menor consumo local; sin expulsiones.","coherence_review":{"status":"implemented","economic_channel":"Precios finales, disponibilidad, beneficiarios y financiación separadas.","social_channel":"Esfuerzo económico automático y preferencias residuales; perfiles transversales sin duplicar población.","evidence":"Fuentes oficiales para referencias y mecanismos; elasticidades, plazos y felicidad son supuestos explícitos y editables."},"additional_homes_at_full":0}'::jsonb else item end order by ord) from jsonb_array_elements(payload->'model'->'measures') with ordinality arr(item,ord))),'{model,sources}',payload->'model'->'sources'||'[{"id":"international_remote_work","title":"Ley 14/2013: teletrabajo internacional, artículos 74 bis a 74 quinquies","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-10074#a74bis","kind":"regulation","accessed":"2026-10-05"},{"id":"international_remote_faq","title":"UGE: requisitos del teletrabajo internacional","url":"https://www.inclusion.gob.es/es/web/unidadgrandesempresas/teletrabajadores","kind":"reference","accessed":"2026-10-05"}]'::jsonb),'{model,release_history}','{"label":"Alfa 0.12","current":"0.12.0-alpha","releases":[{"date":"2026-10-03","label":"Alfa 0.12","changes":["Escenario nacional con demografía dinámica, referencias oficiales y fuentes consultables.","Impuestos y presupuestos ajustables en ambos sentidos, persistentes y con comprobación de financiación.","Informes trimestrales con curvas superpuestas del último año y balance final de partida.","Banco de 120 plantillas de comentarios adaptativos.","Integración en la web, navegación móvil y pie de página común."],"version":"0.12.0-alpha"}],"history_note":"El registro de versiones comienza en Alfa 0.12. Las iteraciones anteriores no disponen de un historial numerado validado.","entries":[{"version":"0.12.0-alpha.collective1.mean1.remote1","date":"2026-10-05","changes":["Sustituida acogida temporal por cupo y umbral de rentas altas para nuevos teletrabajadores internacionales; flujos, demanda, consumo, costes y efectos colectivos propios."]},{"version":"0.12.0-alpha.migration2","date":"2026-10-04","summary":"Migración: presupuesto, expulsiones, retorno con bonus separado, límites acumulados y efectos persistentes; retirada de integración laboral y mediación."},{"version":"0.12.0-alpha.help1","date":"2026-10-04","summary":"Ayudas breves con cifras, reparto de competencias por medida y fuentes oficiales; catálogo cerrado al iniciar."},{"version":"0.12.0-alpha.coherence1","date":"2026-10-04","summary":"Revisión completa de coherencia: esfuerzo de compra, oferta anunciada y mercados segmentados; parque público persistente, capacidad constructiva, inversión privada, reservas de seguros, beneficiarios y perfiles fiscales por hogar. Controles sin efectos heredados, rehabilitación condicionada y programas territoriales sin población ficticia."},{"version":"0.12.0-alpha.collective1","date":"2026-10-05","summary":"Felicidad colectiva ponderada de todos los colectivos nacionales; recortes y presión fiscal con efectos sociales fuertes, PIB real y rebote por sensibilidad de grupo. Indicador en diseño de cada medida."}]}'::jsonb),
